            if numeric(val):
                return str(val)
    for entry in cvss_obj.values():
        if not isinstance(entry, dict):
            continue
        for key in ('V3Score', 'V30Score', 'V2Score'):
            val = entry.get(key)
            if numeric(val):
                return str(val)
    return 'N/A'

def pick_url(vuln):
    url = vuln.get('PrimaryURL')
    if isinstance(url, str) and url.strip():
        return url.strip()
    refs = vuln.get('References')
    if isinstance(refs, list):
        for r in refs:
            if isinstance(r, str) and r.strip():
                return r.strip()
    return 'N/A'

